/**
 * Real `send` instructions, copied account by account from transactions on chain. They are the
 * expected answer for the send builder in lib/client/lzSend.ts: built for the same sender, it
 * must list the same accounts in the same order.
 *
 * `w` is the writable flag as the transaction carried it. A transaction merges flags per
 * account (writable anywhere means writable everywhere), which the test accounts for.
 */
export type CapturedSend = {
    /** The transaction this was copied from. */
    source: string
    /** The wallet that sent it. */
    signer: string
    /** That wallet's token balance account (the entry the tokens were pulled from). */
    tokenSource: string
    accounts: { key: string; w: boolean }[]
}

